'use client'; import type { ReactNode } from 'react';
import { Component, type ErrorInfo } from 'react';
import { AlertTriangle } from 'lucide-react'; type Props = { children: ReactNode; fallbackTitle?: string };
type State = { hasError: boolean }; export class VendorErrorBoundary extends Component<Props, State> { state: State = { hasError: false }; static getDerivedStateFromError(): State { return { hasError: true }; } componentDidCatch(error: Error, info: ErrorInfo) { console.error('[VendorErrorBoundary]', error, info.componentStack); } render() { if (this.state.hasError) { return ( <div role="alert" className="rounded-2xl border border-rose-500/30 bg-rose-500/10 p-6 text-vendor-charcoal " > <div className="flex items-start gap-3"> <AlertTriangle className="h-5 w-5 shrink-0 text-rose-600" aria-hidden /> <div> <p className="font-bold">{this.props.fallbackTitle ?? 'Module failed to load'}</p> <p className="mt-1 text-sm text-vendor-muted text-vendor-muted"> Refresh the page or contact Nexora support if the issue persists. Audit logs capture this event. </p> <button type="button" onClick={() => this.setState({ hasError: false })} className="mt-3 rounded-lg bg-vendor-secondary px-3 py-1.5 text-xs font-bold text-white hover:opacity-90" > Retry </button> </div> </div> </div> ); } return this.props.children; }
}
